use super::*;
#[path="../../mbse-exchange/tests/support/project_set_source.rs"]
mod fixture;
use mbse_exchange::project_sets::FileState;
fn setup()->(tempfile::TempDir,Browser,egui::Context){let a=tempfile::tempdir_in(std::env::var_os("TMPDIR").unwrap()).unwrap();let path=fixture::prepare(a.path());let mut b=Browser::default();b.open_window(path.to_str().unwrap());(a,b,egui::Context::default())}
fn render(b:&mut Browser,ctx:&egui::Context,events:Vec<egui::Event>)->Vec<String>{let out=ctx.run_ui(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(2200.,1600.))),focused:true,events,..Default::default()},|_|{b.bounds=b.show(ctx);});let copies=out.platform_output.commands.iter().filter_map(|c|if let egui::OutputCommand::CopyText(s)=c{Some(s.clone())}else{None}).collect();out.drop_without_applying_deltas();copies}
fn settle(b:&mut Browser,ctx:&egui::Context){for _ in 0..4{render(b,ctx,vec![]);}}
fn wait(b:&mut Browser,ctx:&egui::Context){for _ in 0..200{settle(b,ctx);if !b.pending(){return;}std::thread::sleep(std::time::Duration::from_millis(5));}panic!("source worker timeout");}
fn click(b:&mut Browser,ctx:&egui::Context,key:&str)->Vec<String>{settle(b,ctx);let rect=b.bounds[key];assert!(rect[3]-rect[1]>12.,"clipped {key}");let p=egui::pos2((rect[0]+rect[2])/2.,(rect[1]+rect[3])/2.);let mut out=Vec::new();for pressed in[true,false]{out.extend(render(b,ctx,vec![egui::Event::PointerMoved(p),egui::Event::PointerButton{pos:p,button:egui::PointerButton::Primary,pressed,modifiers:egui::Modifiers::NONE}]));}settle(b,ctx);out}
fn fill(b:&mut Browser,ctx:&egui::Context,key:&str,text:&str){click(b,ctx,key);render(b,ctx,vec![egui::Event::Key{key:egui::Key::A,physical_key:None,pressed:true,repeat:false,modifiers:egui::Modifiers{ctrl:true,command:true,..Default::default()}},egui::Event::Text(text.into())]);settle(b,ctx);}
fn opened(b:&mut Browser,ctx:&egui::Context){click(b,ctx,"projects:Open");wait(b,ctx);assert!(b.source.is_some(),"{}",b.note);}
#[test]
fn rendered_project_set_open_member_filter_and_selection_keep_duplicate_native_and_external_ids_distinct(){
 let(a,mut b,ctx)=setup();opened(&mut b,&ctx);assert_eq!(b.source.as_ref().unwrap().summary().members.len(),4);fill(&mut b,&ctx,"projects:filter","System #1");assert_eq!(b.rows.len(),2);click(&mut b,&ctx,"projects:element:0");let left=b.selected.clone().unwrap();assert_eq!(left.member,"left");assert!(!b.detail.contains("Supplier System"));click(&mut b,&ctx,"projects:element:1");let right=b.selected.clone().unwrap();assert_eq!(right.member,"right");assert_ne!(left,right);assert!(b.detail.contains("Supplier System"));click(&mut b,&ctx,"projects:member:supplier");fill(&mut b,&ctx,"projects:filter","Shared local ID");assert_eq!(b.rows.len(),1);click(&mut b,&ctx,"projects:element:0");let supplier=b.selected.clone().unwrap();click(&mut b,&ctx,"projects:member:consumer");click(&mut b,&ctx,"projects:element:0");let consumer=b.selected.clone().unwrap();assert_ne!(supplier,consumer);assert_eq!(supplier.identity,consumer.identity);assert_eq!(std::fs::read(a.path().join("left/native.kernspan")).unwrap(),fixture::NATIVE);assert_eq!(std::fs::read(a.path().join("left/native.mbse-views.json")).unwrap(),fixture::VIEWS);
}
#[test]
fn rendered_project_set_missing_changed_companions_copy_and_clear_are_readonly_and_selection_is_qualified(){
 let(a,mut b,ctx)=setup();opened(&mut b,&ctx);let s=b.source.as_ref().unwrap().summary();assert!(s.members[0].companions[0].bound_declaration_checked);assert_eq!(s.members[0].companions[1].file.state,FileState::Missing);assert_eq!(s.members[0].companions[2].file.state,FileState::Changed);click(&mut b,&ctx,"projects:element:0");let copy=click(&mut b,&ctx,"projects:Copy");assert_eq!(copy.len(),1);let value:serde_json::Value=serde_json::from_str(&copy[0]).unwrap();assert_eq!(value["selected"]["member"],"left");assert_eq!(value["summary"]["members"][0]["companions"][1]["file"]["state"],"Missing");click(&mut b,&ctx,"projects:Clear");assert!(b.source.is_none()&&b.selected.is_none()&&b.last_check.is_none()&&b.rows.is_empty());assert_eq!(std::fs::read(a.path().join("left/native.kernspan")).unwrap(),fixture::NATIVE);
}
#[test]
fn rendered_project_set_recheck_and_failed_open_retain_frozen_data_and_never_retarget_a_edited_path(){
 let(a,mut b,ctx)=setup();opened(&mut b,&ctx);click(&mut b,&ctx,"projects:Recheck");wait(&mut b,&ctx);assert!(b.last_check.as_ref().unwrap().as_ref().unwrap().unchanged);let old=b.source.as_ref().unwrap().clone();let key=old.keys("left")[0].clone();let record=old.native_record(&key).unwrap().clone();let mut bytes=fixture::NATIVE.to_vec();bytes.push(b' ');std::fs::write(a.path().join("left/native.kernspan"),&bytes).unwrap();fill(&mut b,&ctx,"projects:path",a.path().join("not-listed.mbse-projects.json").to_str().unwrap());click(&mut b,&ctx,"projects:Recheck");wait(&mut b,&ctx);assert!(!b.last_check.as_ref().unwrap().as_ref().unwrap().unchanged);assert_eq!(b.source.as_ref().unwrap().native_record(&key).unwrap(),&record);click(&mut b,&ctx,"projects:Open");wait(&mut b,&ctx);assert!(b.error);assert!(Arc::ptr_eq(b.source.as_ref().unwrap(),&old));assert!(!b.last_check.as_ref().unwrap().as_ref().unwrap().unchanged);
}
#[test]
fn rendered_project_set_window_reopen_keeps_frozen_session_but_cold_browser_requires_explicit_open(){
 let(_a,mut b,ctx)=setup();opened(&mut b,&ctx);click(&mut b,&ctx,"projects:element:0");let source=b.source.clone().unwrap();let selected=b.selected.clone();click(&mut b,&ctx,"projects:Close");assert!(!b.visible);b.open_window("/workspace/other.mbse-projects.json");settle(&mut b,&ctx);assert!(Arc::ptr_eq(b.source.as_ref().unwrap(),&source));assert_eq!(b.selected,selected);assert!(!b.path.contains("other"));let mut cold=Browser::default();cold.open_window(&b.path);settle(&mut cold,&ctx);assert!(cold.source.is_none()&&cold.selected.is_none()&&!cold.pending());
}
#[test]
fn rendered_project_set_pending_worker_prevents_reopen_recheck_and_clear_and_disconnection_retains_previous_capture(){
 let(_a,mut b,ctx)=setup();opened(&mut b,&ctx);let source=b.source.clone().unwrap();let(tx,rx)=mpsc::channel();b.pending=Some(rx);b.checking=true;settle(&mut b,&ctx);for key in["projects:Open","projects:Recheck","projects:Clear"]{click(&mut b,&ctx,key);assert!(b.pending());assert!(Arc::ptr_eq(b.source.as_ref().unwrap(),&source));}drop(tx);wait(&mut b,&ctx);assert!(b.error&&b.last_check.as_ref().unwrap().is_err());assert!(Arc::ptr_eq(b.source.as_ref().unwrap(),&source));
}
#[test]
fn rendered_project_set_import_entry_requires_one_semantic_member_and_emits_only_frozen_source_context(){
 let(_a,mut b,ctx)=setup();opened(&mut b,&ctx);click(&mut b,&ctx,"projects:Review import");assert!(b.take_import_request().is_none());click(&mut b,&ctx,"projects:member:left");click(&mut b,&ctx,"projects:Review import");assert!(b.take_import_request().is_none());click(&mut b,&ctx,"projects:member:supplier");click(&mut b,&ctx,"projects:Review import");let request=b.take_import_request().unwrap();assert_eq!(request.member,"supplier");assert!(Arc::ptr_eq(&request.source,b.source.as_ref().unwrap()));assert!(!b.visible);assert!(b.take_import_request().is_none());
}
